#!/usr/bin/env bash
# Register a tracker with AWS IoT Core and write its credentials to certs/<thing-name>/.
#
#   scripts/provision-device.sh <thing-name>
#
# Requires the GpsTracker stack to be deployed (it owns the device policy) and AWS CLI credentials.
# The private key is generated by AWS and only shown once — keep the certs/ directory safe.
set -euo pipefail

THING="${1:?usage: $0 <thing-name>}"
POLICY="GpsTrackerDevicePolicy"
REGION="ap-southeast-2"

# Every AWS call targets $REGION, whatever the profile or environment says.
aws() { command aws --region "$REGION" "$@"; }

if [[ ! "$THING" =~ ^[a-zA-Z0-9_-]{1,64}$ ]]; then
  echo "thing name must match [a-zA-Z0-9_-]{1,64} (it is used in MQTT topics)" >&2
  exit 1
fi

OUT="$(cd "$(dirname "$0")/.." && pwd)/certs/$THING"
if [[ -e "$OUT" ]]; then
  echo "$OUT already exists, refusing to overwrite" >&2
  exit 1
fi

# Fail before creating anything if the CLI has no credentials or the stack isn't deployed.
ACCOUNT=$(aws sts get-caller-identity --query Account --output text)
if ! aws iot get-policy --policy-name "$POLICY" >/dev/null 2>&1; then
  echo "IoT policy $POLICY not found in account $ACCOUNT ($REGION): deploy the stack first" >&2
  exit 1
fi
echo "Provisioning $THING in account $ACCOUNT ($REGION, profile ${AWS_PROFILE:-<none>})"

mkdir -p "$OUT"
chmod 700 "$OUT"
# Don't leave a half-written directory behind: it would block a retry.
trap 'rc=$?; if [[ $rc -ne 0 ]]; then rm -rf "$OUT"; echo "failed, removed $OUT (AWS resources created so far are not rolled back)" >&2; fi' EXIT

aws iot create-thing --thing-name "$THING" >/dev/null

CERT_ARN=$(aws iot create-keys-and-certificate --set-as-active \
  --certificate-pem-outfile "$OUT/device.pem.crt" \
  --private-key-outfile "$OUT/private.pem.key" \
  --query certificateArn --output text)
chmod 600 "$OUT/private.pem.key"

aws iot attach-policy --policy-name "$POLICY" --target "$CERT_ARN"
aws iot attach-thing-principal --thing-name "$THING" --principal "$CERT_ARN"

curl -fsS -o "$OUT/AmazonRootCA1.pem" https://www.amazontrust.com/repository/AmazonRootCA1.pem

ENDPOINT=$(aws iot describe-endpoint --endpoint-type iot:Data-ATS --query endpointAddress --output text)
echo "$CERT_ARN" > "$OUT/certificate-arn.txt"

cat <<EOF
Provisioned $THING
  credentials: $OUT
  endpoint:    $ENDPOINT:8883
  client id:   $THING
  publish to:  trackers/$THING/telemetry, trackers/$THING/status
  subscribe:   trackers/$THING/cmd
EOF
